inputs.script:
const p = window.__rzn_params || {};
const input = document.querySelector("input[name='req'], input[name='q'][type='search']");
const form = input?.form;
if (!form) throw new Error('No search form');
const sort = p.sort || 'relevance';
if (input.name === 'q' && sort !== 'relevance') {
  let control = form.querySelector('[name="sort"]');
  if (!control) { control = document.createElement('input'); control.type = 'hidden'; control.name = 'sort'; form.appendChild(control); }
  control.value = sort === 'year_desc' ? 'newest' : 'oldest';
}
return { sort: sort };

if (document.querySelector('#ddg-captcha')) throw new Error('site_challenge: complete manual verification in the browser');
const p = window.__rzn_params || {};
const norm = (s) => String(s || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
const fmt = norm(p.format).toLowerCase();
const abs = (h) => { try { const u = new URL(h, location.href); return /^https?:$/.test(u.protocol) ? u.href : ''; } catch { return ''; } };
const t = document.querySelector('#tablelibgen');
const cands = [];
if (t) {
  for (const r of t.querySelectorAll('tbody tr')) {
    const c = r.children;
    if (c.length < 9) continue;
    const titleA = c[0].querySelector('a[href*="edition.php"], a[href*="file.php"]') || c[0].querySelector('a');
    const title = norm(titleA ? titleA.textContent : c[0].textContent);
    if (!title) continue;
    const md5A = Array.from(c[8].querySelectorAll('a')).find(a => /md5=([a-f0-9]{32})/i.test(a.getAttribute('href') || ''));
    const md5 = ((md5A?.getAttribute('href') || '').match(/md5=([a-f0-9]{32})/i) || [])[1] || '';
    cands.push({title, author: norm(c[1].textContent), publisher: norm(c[2].textContent), year: norm(c[3].textContent), language: norm(c[4].textContent), pages: norm(c[5].textContent), size: norm(c[6].textContent), ext: norm(c[7].textContent).toLowerCase(), md5: md5.toLowerCase(), edition_url: abs(titleA?.getAttribute('href') || ''), file_url: abs(c[6].querySelector('a[href*="file.php"]')?.getAttribute('href') || '')});
  }
} else {
  // Restrict to title links in main: the header ticker also contains /md5/ links.
  for (const a of document.querySelectorAll('main a.js-vim-focus[href^="/md5/"]')) {
    const card = a.parentElement.parentElement;
    const meta = Array.from(card.children).find(e => e.classList.contains('font-semibold'));
    const parts = norm(meta?.textContent || meta?.childNodes[0]?.textContent).split(' · ').map(norm);
    const extension = parts.find(x => /^(epub|pdf|mobi|azw3|azw|lit|fb2|djvu|djv|cbr|cbz|zip|txt|rtf|doc|docx|html)$/i.test(x)) || '';
    const size = parts.find(x => /^\d+(?:[.,]\d+)?\s*[KMGT]?i?B$/i.test(x)) || '';
    const language = parts[0] === extension || parts[0] === size || /^\d{4}$/.test(parts[0]) ? '' : (parts[0] || '').replace(/\s*\[[^\]]+\]$/, '');
    const links = Array.from(a.parentElement.querySelectorAll('a[href^="/search?"]'));
    const md5 = (a.getAttribute('href').match(/\/md5\/([a-f0-9]{32})/i) || [])[1];
    if (!md5 || !norm(a.textContent)) continue;
    cands.push({title: norm(a.textContent), author: norm(links[0]?.textContent), publisher: norm(links[1]?.textContent), year: parts.find(x => /^\d{4}$/.test(x)) || '', language, pages: '', size, ext: extension.toLowerCase(), md5: md5.toLowerCase(), edition_url: abs(a.getAttribute('href')), file_url: abs(a.getAttribute('href'))});
  }
}
const empty = /^Files\s*0$/.test(norm(document.querySelector('.nav-tabs .nav-link.active')?.textContent)) || /no (?:files|results) found/i.test(document.querySelector('main')?.textContent || '');
const layout_ok = !!t || cands.length > 0 || empty;
if (!['relevance', 'year_desc', 'year_asc'].includes(p.sort || 'relevance')) throw new Error('Invalid sort');
if (p.sort === 'year_desc' || p.sort === 'year_asc') {
  const year = x => { const m = x.year.match(/\b(\d{4})\b/); return m ? Number(m[1]) : null; };
  cands.sort((a,b) => { const ay = year(a), by = year(b); return ay === null ? (by === null ? 0 : 1) : by === null ? -1 : (p.sort === 'year_asc' ? ay-by : by-ay); });
}
const limit = Math.min(100, Math.max(1, Number(p.limit) || 25));
const results = cands.filter(x => !fmt || x.ext === fmt).slice(0, limit);
return {layout_ok, query: norm(p.query) || null, format: fmt || null, sort: p.sort || 'relevance', count: results.length, results, ...(!layout_ok ? {error: 'Unsupported book source layout.'} : {})};
